I did not add the enrichment fetch. It would need `aap:caps/http-client`, but the node's `with` clause grants only `aap:caps/notifier@0.1.0`, so the world cannot import it. The node below only notifies, and its output is unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let mut message = format!(
            "Digest {}: {}\n({} entries, {} considered)",
            composed.date,
            composed.overview,
            kept,
            composed.considered.len()
        );
        for e in composed.entries.iter().filter(|e| e.kept) {
            message.push_str(&format!("\n- {} {}", e.title, e.link));
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
